{"code":"const files = ['tests/test_connectors.py','tests/test_idempotency.py','tests/test_pipeline.py','tests/test_reconcile.py','tests/test_legacy.py','scripts/replay_incidents.py','pytest.ini','skills/bug-fix/SKILL.md'];
const out = {};
