{"code":"const files = [];
for (let i=3;i<=12;i++) files.push('chronos/connectors/conn_'+String(i).padStart(2,'0')+'.py');
for (let i=13;i<=16;i++) files.push('chronos/connectors/regional/conn_'+i+'.py');
const out = {};
for (const f of files) { const r = await ms.read(f, {format:'json', lineCount: 400}); out[f] = r.text.replace(/def _clean_amount[\s\S]*?\n\n\n/, '<CLEAN>\n').replace(/def _parse_ts[\s\S]*?\n\n\n/, '<PARSE>\n'); }
return out;"}

{"code":"const r = await ms.search('def _clean_amount|def _parse_ts|return round|replace\\(tzinfo|DEFAULT_TZ|tzinfo=|return datetime', {path:'chronos/connectors', regex:true, maxMatches:200});
const bodies = {};
for (const h of r.hits) bodies[h.path+':'+h.line] = h.text;
const s = await ms.search('_clean_amount|_parse_ts', {path:'.', regex:true, maxMatches:200});
return {bodies, usage: s.hits.map(h=>h.path+':'+h.line+' '+h.text)};"}

